#!/usr/bin/env bash
# deploy.sh — One-command production deploy for Yabanin on a VPS.
# Usage: ./scripts/deploy.sh [version]
#   version defaults to latest from git HEAD.
# Prerequisites: docker, docker compose, secrets generated by
#   ./scripts/deploy/init-secrets.sh (deploy/.env + deploy/secrets/).

set -euo pipefail

VERSION="${1:-$(git rev-parse --short HEAD)}"
BASE_DIR="$(cd "$(dirname "$0")/.." && pwd)"
COMPOSE_FILE="$BASE_DIR/deploy/docker-compose.prod.yml"

# Profile selection (N11-P01-T02). Production deploys default to the full
# real-model stack. A PostgreSQL-only production install (I30 — no
# classifier/embedder/llama-server; rule-tier classifier, exact-Redis cache)
# opts out explicitly:
#   COMPOSE_PROFILES= ./scripts/deploy.sh
# NOTE: "${VAR-def}" without ':' — an explicitly EMPTY COMPOSE_PROFILES must
# survive; "${VAR:-def}" would substitute the default for the empty value.
COMPOSE_PROFILES="${COMPOSE_PROFILES-real-models}"
export COMPOSE_PROFILES

case ",$COMPOSE_PROFILES," in
    *,real-models,*)
        REAL_MODELS=1
        # Wire the in-stack ML endpoints for the real-models profile. Values
        # already set in the operator's shell environment win. NOTE: deploy.sh
        # never sources deploy/.env — under this default profile the exports
        # below outrank a deploy/.env value for these 5 ML vars; .env values
        # take effect only in PGO mode (COMPOSE_PROFILES=) or a plain
        # `docker compose up` invoked without this script.
        export YABANIN_CLASSIFIER_SERVICE_URL="${YABANIN_CLASSIFIER_SERVICE_URL:-http://classifier:8080}"
        export YABANIN_EMBEDDER_ENABLED="${YABANIN_EMBEDDER_ENABLED:-true}"
        export YABANIN_EMBEDDER_BASE_URL="${YABANIN_EMBEDDER_BASE_URL:-http://embedder:8080}"
        export YABANIN_EMBEDDER_MODEL="${YABANIN_EMBEDDER_MODEL:-BAAI/bge-small-en-v1.5}"
        export YABANIN_EMBEDDER_ENDPOINT="${YABANIN_EMBEDDER_ENDPOINT:-tei}"
        ;;
    *)
        REAL_MODELS=0
        echo "Profile: PostgreSQL-only (classifier/embedder/llama-server stay down — I30)"
        ;;
esac

# Services that must be healthy after deployment. classifier/embedder exist
# only in the real-models profile (deploy/docker-compose.prod.yml), so they
# are in the wait lists only when that profile is on — a profiled-off service
# would otherwise fail the health loop and abort a healthy install.
if [ "$REAL_MODELS" = "1" ]; then
    ALL_SERVICES=(postgres redis gateway admin loggerd caddy prometheus alertmanager grafana dashboard-web classifier embedder backup node-exporter)
else
    ALL_SERVICES=(postgres redis gateway admin loggerd caddy prometheus alertmanager grafana dashboard-web backup node-exporter)
fi

# Core services used for health-checking (migrate + backup are one-shot/cron, excluded from health loop)
HEALTHY_SERVICES=(postgres redis gateway admin loggerd caddy prometheus alertmanager grafana dashboard-web)

echo "=== Yabanin Production Deploy ==="
echo "Version: $VERSION"
echo "Base dir: $BASE_DIR"

# Pre-flight checks
echo "[0/7] Running pre-flight checks..."

# Fail fast with an actionable message when the generated secrets are missing
# (otherwise compose fails deep inside `up` with opaque per-service errors).
MISSING_SECRETS=""
for f in .env secrets/pg_uri secrets/session_key secrets/cache_hmac secrets/kms_local_key secrets/metrics-bearer.key; do
    [ -s "$BASE_DIR/deploy/$f" ] || MISSING_SECRETS="$MISSING_SECRETS deploy/$f"
done
if [ -n "$MISSING_SECRETS" ]; then
    echo "FATAL: required deploy secrets are missing:$MISSING_SECRETS"
    echo "       Generate them with:  ./scripts/deploy/init-secrets.sh"
    echo "       (then review deploy/.env: domains, markup, ALERT_WEBHOOK_URL)"
    exit 1
fi

# GRAFANA_ADMIN_PASSWORD may live in deploy/.env (compose interpolation reads
# it from there); only require it as an env var when .env does not carry it.
if [ -z "${GRAFANA_ADMIN_PASSWORD:-}" ]; then
    GRAFANA_ADMIN_PASSWORD="$(grep -E '^GRAFANA_ADMIN_PASSWORD=' "$BASE_DIR/deploy/.env" | tail -1 | cut -d= -f2- || true)"
    if [ -z "$GRAFANA_ADMIN_PASSWORD" ]; then
        echo "FATAL: GRAFANA_ADMIN_PASSWORD must be set in deploy/.env (or as an env var) before deploying."
        exit 1
    fi
    export GRAFANA_ADMIN_PASSWORD
fi

# 1. Pull latest code
echo "[1/7] Pulling latest..."
git pull --ff-only || true

# 2. Pre-deploy pg_dump snapshot (only if postgres is already running)
echo "[2/7] Creating pre-deploy database snapshot..."
SNAPSHOT_TS="$(date +%Y%m%d_%H%M%S)"
PG_SNAPSHOT="$BASE_DIR/deploy/backups/pg_${SNAPSHOT_TS}.sql.gz"
mkdir -p "$BASE_DIR/deploy/backups"
if docker compose -f "$COMPOSE_FILE" ps postgres 2>/dev/null | grep -q "healthy"; then
    docker compose -f "$COMPOSE_FILE" run --rm postgres pg_dumpall -U "${PG_USER:-yabanin}" | gzip > "$PG_SNAPSHOT"
    echo "  Snapshot saved to $PG_SNAPSHOT"
else
    echo "  Skipping snapshot (postgres not running — first deploy or fresh setup)"
fi

# 3. Build images
echo "[3/7] Building Docker images..."
# All images build from the clean checkout (N11-P01-T02): the unified yabanin
# binary (cmd/yabanin) and the dashboard SPA (web/dashboard/Dockerfile bakes
# web/dashboard/dist — gitignored, absent on a fresh clone).
docker compose -f "$COMPOSE_FILE" build gateway admin loggerd dashboard-web

# 4. Run migrations
echo "[4/7] Running database migrations..."
set +e
MIGRATE_OUTPUT="$(docker compose -f "$COMPOSE_FILE" run --rm migrate 2>&1)"
MIGRATE_RC=$?
set -e
if [ $MIGRATE_RC -ne 0 ]; then
    echo "  Migration failed (exit code $MIGRATE_RC):"
    echo "$MIGRATE_OUTPUT" | tail -5
    echo "  Aborting deploy — database is not up-to-date"
    exit 1
fi
echo "  Migrations applied successfully"

# 5. Deploy ALL services
echo "[5/7] Starting all services..."
docker compose -f "$COMPOSE_FILE" up -d

# 6. Health checks — wait for every service to become healthy (or exit)
echo "[6/7] Waiting for health checks..."
MAX_RETRIES=18
HEALTHY_COUNT=0
UNHEALTHY=""

for svc in "${HEALTHY_SERVICES[@]}"; do
    echo "  Checking $svc..."
    retry=0
    while [ $retry -lt $MAX_RETRIES ]; do
        # Docker compose ps JSON has a "Health" field: "healthy", "unhealthy", or starting/empty.
        # We also accept "Up" as healthy for services without a healthcheck defined.
        STATUS="$(docker compose -f "$COMPOSE_FILE" ps "$svc" --format json 2>/dev/null | python3 -c 'import sys,json; d=json.load(sys.stdin); h=d.get("Health",""); s=d.get("Status",""); print("healthy" if h=="healthy" or (h=="" and s.startswith("Up")) else "unhealthy")' 2>/dev/null || echo "unknown")"
        if [ "$STATUS" = "healthy" ]; then
            echo "  ✓ $svc is healthy"
            HEALTHY_COUNT=$((HEALTHY_COUNT + 1))
            break
        fi
        retry=$((retry + 1))
        sleep 2
    done
    if [ $retry -ge $MAX_RETRIES ]; then
        UNHEALTHY="${UNHEALTHY} ${svc}"
        echo "  ✗ $svc FAILED health check after $((MAX_RETRIES * 2))s — exiting"
    fi
done

if [ -n "$UNHEALTHY" ]; then
    echo ""
    echo "FATAL: The following services are unhealthy:$UNHEALTHY"
    echo "See logs with: docker compose -f $COMPOSE_FILE logs <service>"
    echo "Rolling back to previous snapshot..."
    # Attempt restore from the snapshot we just took
    if [ -f "$PG_SNAPSHOT" ]; then
        echo "  Restoring from $PG_SNAPSHOT ..."
        zcat "$PG_SNAPSHOT" | docker compose -f "$COMPOSE_FILE" run --rm postgres psql -U "${PG_USER:-yabanin}" || true
    fi
    exit 1
fi

echo ""
echo "  All $HEALTHY_COUNT services are healthy."

# 7. Summary
echo "[7/7] Deploy complete!"
echo ""
echo "  Gateway:   https://api.${API_DOMAIN:-yourdomain.com}"
echo "  Admin:     https://admin.${ADMIN_DOMAIN:-yourdomain.com}"
echo "  Dashboard: https://dash.${DASHBOARD_DOMAIN:-yourdomain.com}"
echo "  Grafana:   http://localhost:3001"
echo ""
echo "  Version: $VERSION"
if [ "$REAL_MODELS" = "1" ]; then
    echo "  Profile:   real-models (classifier/embedder/llama-server up)"
else
    echo "  Profile:   PostgreSQL-only (no ML services; rule-tier + exact-Redis cache)"
fi
docker compose -f "$COMPOSE_FILE" ps
